const n = (v: number) => v.toLocaleString("ko-KR");
const p = (r: number, d = 2) => `${(r * 100).toFixed(d)}%`;
const man = (v: number) => `${n(Math.round(v / 10_000))}만 원`;
const monthly209 = RATES.minimumWage * 209;
const net = (annual: number) =>
  calcNetSalary({ annualSalary: annual, monthlyNonTaxable: RATES.incomeTax.mealTaxFreeLimit, dependents: 1, children: 0 });

